private final String sideString;
public int rType;
public BlockPipe(Material material, String texture, int renderType) {
    super(material);
    sideString = texture;
    rType = renderType;
    setDefaultState(blockState.getBaseState().withProperty(METADATA, 0));
    setSoundType(ModSoundTypes.grate);
}
